2	
3	// Regression tests for append transaction integrity:
4	//
5	//   - concurrent auto-sequenced appends on one service instance must all
6	//     return 201, save each request exactly once with a contiguous chain,
7	//     and keep every business field verbatim;
8	//   - concurrent requests racing for one explicit next seq must elect
9	//     exactly one winner (201) while the others get 409 audit_seq_conflict;
10	//   - a controlled write failure while the database stays readable must
11	//     surface as 503 storage_unavailable, consume no sequence number and
12	//     leave the chain tail untouched until writes recover.
13	//
14	// Every scenario cross-checks the 201 response against the rows actually
15	// persisted in a temporary SQLite database (read through a separate
16	// connection), recomputes each hash from the public SHA-256 rule in
17	// README.md rather than calling product internals, and repeats the full
18	// verification after the database is closed and reopened.
19	
20	import (
21		"database/sql"
22		"encoding/json"
23		"net/http"
24		"net/http/httptest"
25		"path/filepath"
26		"strings"
27		"sync"
28		"testing"
29	
30		"github.com/xjeey8iust/sen-audit-ledger/internal/store"
31	)
32	
33	// createdEvent is the typed 201 response body.
34	type createdEvent struct {
35		Account    string `json:"account"`
36		Operation  string `json:"operation"`
37		Resource   string `json:"resource"`
38		Result     string `json:"result"`
39		OccurredAt string `json:"occurred_at"`
40		Seq        int64  `json:"seq"`
41		PrevHash   string `json:"prev_hash"`
42		Hash       string `json:"hash"`
43	}
44	
45	// eventRequest builds one POST /events body. Seq is omitted when nil.
46	type eventRequest struct {
47		Account    string `json:"account"`
48		Operation  string `json:"operation"`
49		Resource   string `json:"resource"`
50		Result     string `json:"result"`
51		OccurredAt string `json:"occurred_at"`
52		Seq        *int64 `json:"seq,omitempty"`
53	}
54	
55	// eventFixture pairs a request with the UTC form the service must store.
56	type eventFixture struct {
57		req         eventRequest
58		occurredUTC string
59	}
60	
61	// ledgerRecord is the business-field expectation for one persisted row.
62	type ledgerRecord struct {
63		account    string
64		operation  string
65		resource   string
66		result     string
67		occurredAt string
68	}
69	
70	// persistedEvent is one row read back through an independent connection.
71	type persistedEvent struct {
72		seq        int64
73		account    string
74		operation  string
75		resource   string
76		result     string
77		occurredAt string
78		prevHash   string
79		hash       string
80	}
81	
82	func openStoreAt(t *testing.T, path string) *store.Store {
83		t.Helper()
84		st, err := store.Open(path)
85		if err != nil {
86			t.Fatalf("open store %s: %v", path, err)
87		}
88		return st
89	}
90	
91	func closeStore(t *testing.T, st *store.Store) {
92		t.Helper()
93		if err := st.Close(); err != nil {
94			t.Fatalf("close store: %v", err)
95		}
96	}
97	
98	func mustEventJSON(t *testing.T, e eventRequest) string {
99		t.Helper()
100		var b strings.Builder
101		encoder := json.NewEncoder(&b)
102		// Keep non-ASCII and angle brackets raw in the request; the server
103		// decodes either way and hashes the decoded text.
104		encoder.SetEscapeHTML(false)
105		if err := encoder.Encode(e); err != nil {
106			t.Fatalf("encode event: %v", err)
107		}
108		return b.String()
109	}
110	
111	func postStructuredEvent(t *testing.T, router http.Handler, e eventRequest) *httptest.ResponseRecorder {
112		t.Helper()
113		return postEventBody(t, router, mustEventJSON(t, e))
114	}
115	
116	func decodeCreated(t *testing.T, recorder *httptest.ResponseRecorder) createdEvent {
117		t.Helper()
118		var got createdEvent
119		if err := json.Unmarshal(recorder.Body.Bytes(), &got); err != nil {
120			t.Fatalf("decode 201 body: %v (%s)", err, recorder.Body.String())
121		}
122		return got
123	}
124	
125	// assertErrorEnvelope checks the published error contract for 409/503
126	// responses: exactly one top-level error object whose code and message are
127	// non-empty strings, with no SQL, stack frame or file path in the body.
128	func assertErrorEnvelope(t *testing.T, recorder *httptest.ResponseRecorder, status int, code string) {
129		t.Helper()
130		if recorder.Code != status {
131			t.Fatalf("status = %d, want %d (%s)", recorder.Code, status, recorder.Body.String())
132		}
133		var body map[string]any
134		if err := json.Unmarshal(recorder.Body.Bytes(), &body); err != nil {
135			t.Fatalf("decode error body: %v (%s)", err, recorder.Body.String())
136		}
137		if len(body) != 1 {
138			t.Fatalf("top-level keys = %v, want only the error object", body)
139		}
140		errObj, ok := body["error"].(map[string]any)
141		if !ok {
142			t.Fatalf("error = %v, want an object", body["error"])
143		}
144		if len(errObj) != 2 {
145			t.Fatalf("error keys = %v, want only code and message", errObj)
146		}
147		if errObj["code"] != code {
148			t.Fatalf("code = %v, want %s", errObj["code"], code)
149		}
150		message, ok := errObj["message"].(string)
151		if !ok || message == "" {
152			t.Fatalf("message = %v, want a non-empty string", errObj["message"])
153		}
154		for _, leak := range []string{"sql", "SQL", "SELECT", "INSERT", "UPDATE", "goroutine", ".go", "/", "\\"} {
155			if strings.Contains(recorder.Body.String(), leak) {
156				t.Fatalf("error response leaks %q: %s", leak, recorder.Body.String())
157			}
158		}
159	}
160	
161	// readFullLedger opens the database file independently of the service and
162	// returns every persisted record in seq order.
163	func readFullLedger(t *testing.T, path string) []persistedEvent {
164		t.Helper()
165		db, err := sql.Open("sqlite", path)
166		if err != nil {
167			t.Fatalf("open sqlite: %v", err)
168		}
169		defer db.Close()
170		rows, err := db.Query(`SELECT seq, account, operation, resource, result, occurred_at, prev_hash, hash
171			FROM events ORDER BY seq`)
172		if err != nil {
173			t.Fatalf("query events: %v", err)
174		}
175		defer rows.Close()
176		var events []persistedEvent
177		for rows.Next() {
178			var e persistedEvent
179			if err := rows.Scan(&e.seq, &e.account, &e.operation, &e.resource, &e.result,
180				&e.occurredAt, &e.prevHash, &e.hash); err != nil {
181				t.Fatalf("scan event: %v", err)
182			}
183			events = append(events, e)
184		}
185		if err := rows.Err(); err != nil {
186			t.Fatalf("iterate events: %v", err)
187		}
188		return events
189	}
190	
191	// verifyLedger compares the whole persisted chain with the successful
192	// responses: exact row count, contiguous seqs from 1, verbatim business
193	// fields, genesis/previous-hash linkage, and hashes recomputed from the
194	// public rule. responseHash additionally pins each stored hash to the hash
195	// handed back in that seq's 201 response.
196	func verifyLedger(t *testing.T, path string, want []ledgerRecord, responseHash map[int64]string) []persistedEvent {
197		t.Helper()
198		events := readFullLedger(t, path)
199		if len(events) != len(want) {
200			t.Fatalf("persisted %d events, want %d: %+v", len(events), len(want), events)
201		}
202		prev := strings.Repeat("0", 64)
203		for i, expected := range want {
204			e := events[i]
205			if e.seq != int64(i+1) {
206				t.Fatalf("row %d: seq = %d, want %d (chain must stay contiguous)", i, e.seq, i+1)
207			}
208			if e.account != expected.account || e.operation != expected.operation ||
209				e.resource != expected.resource || e.result != expected.result ||
210				e.occurredAt != expected.occurredAt {
211				t.Fatalf("row %d business fields = %+v, want %+v", i, e, expected)
212			}
213			if e.prevHash != prev {
214				t.Fatalf("row %d prev_hash = %s, want %s", i, e.prevHash, prev)
215			}
216			recomputed := wantHash(e.seq, expected.account, expected.operation, expected.resource,
217				expected.result, expected.occurredAt, e.prevHash)
218			if e.hash != recomputed {
219				t.Fatalf("row %d hash = %s, want %s per the public rule", i, e.hash, recomputed)
220			}
221			if e.hash != responseHash[e.seq] {
222				t.Fatalf("row %d stored hash = %s, 201 response hash = %s", i, e.hash, responseHash[e.seq])
223			}
224			prev = e.hash
225		}
226		return events
227	}
